import { pool } from '../../../packages/database/src/pool.js';

export type ErasureStatus = 'pending' | 'processing' | 'failed' | 'completed';

export interface ErasureRequestRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  status: ErasureStatus;
  attempts: number;
  max_attempts: number;
  completed_steps: string[];
  last_error: string | null;
  created_at: Date;
  updated_at: Date;
  completed_at: Date | null;
}

export interface ErasurePublicView {
  id: string;
  customerId: string;
  status: ErasureStatus;
  attempts: number;
  createdAt: string;
  updatedAt: string;
  completedAt: string | null;
  lastError: string | null;
}

export function toErasurePublicView(row: ErasureRequestRow): ErasurePublicView {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    completedAt: row.completed_at ? row.completed_at.toISOString() : null,
    lastError: row.last_error,
  };
}

export class ErasureRepository {
  async customerExists(merchantId: string, customerId: string): Promise<boolean> {
    const result = await pool.query(
      `SELECT 1 FROM customers.customers WHERE merchant_id=$1 AND id=$2
       UNION ALL
       SELECT 1 FROM customers.erasure_tombstones WHERE merchant_id=$1 AND customer_id=$2
       LIMIT 1`,
      [merchantId, customerId],
    );
    return Boolean(result.rowCount);
  }

  async findById(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  async findByCustomer(merchantId: string, customerId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async createOrGetExisting(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
  ): Promise<ErasureRequestRow> {
    const existing = await client.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2 FOR UPDATE`,
      [merchantId, customerId],
    );
    if (existing.rows[0]) return existing.rows[0];

    const created = await client.query<ErasureRequestRow>(
      `INSERT INTO customers.erasure_requests(merchant_id,customer_id,status)
       VALUES($1,$2,'pending')
       ON CONFLICT(merchant_id,customer_id) DO UPDATE
       SET updated_at=customers.erasure_requests.updated_at
       RETURNING *`,
      [merchantId, customerId],
    );
    return created.rows[0]!;
  }

  async claimNext(workerId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `UPDATE customers.erasure_requests
       SET status='processing', attempts=attempts+1, updated_at=now(), last_error=NULL
       WHERE id=(
         SELECT id FROM customers.erasure_requests
         WHERE status IN ('pending','failed')
           AND attempts < max_attempts
         ORDER BY updated_at, created_at
         FOR UPDATE SKIP LOCKED
         LIMIT 1
       )
       RETURNING *`,
    );
    void workerId;
    return result.rows[0];
  }

  async markStepComplete(client: pg.PoolClient, requestId: string, step: string): Promise<string[]> {
    const result = await client.query<{ completed_steps: string[] }>(
      `UPDATE customers.erasure_requests
       SET completed_steps = CASE
             WHEN $2 = ANY(completed_steps) THEN completed_steps
             ELSE array_append(completed_steps, $2)
           END,
           updated_at=now()
       WHERE id=$1
       RETURNING completed_steps`,
      [requestId, step],
    );
    return result.rows[0]?.completed_steps ?? [];
  }

  async markCompleted(client: pg.PoolClient, requestId: string): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET status='completed', completed_at=now(), updated_at=now(), last_error=NULL
       WHERE id=$1`,
      [requestId],
    );
  }

  async markFailed(requestId: string, errorCode: string): Promise<void> {
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status=CASE WHEN attempts >= max_attempts THEN 'failed' ELSE 'failed' END,
           last_error=$2, updated_at=now()
       WHERE id=$1`,
      [requestId, errorCode],
    );
  }

  async insertTombstone(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
    requestId: string,
  ): Promise<void> {
    await client.query(
      `INSERT INTO customers.erasure_tombstones(merchant_id,customer_id,erasure_request_id)
       VALUES($1,$2,$3)
       ON CONFLICT(merchant_id,customer_id) DO NOTHING`,
      [merchantId, customerId, requestId],
    );
  }

  async isErased(merchantId: string, customerId: string): Promise<boolean> {
    const result = await pool.query(
      `SELECT 1 FROM customers.erasure_tombstones WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return Boolean(result.rowCount);
  }

  async isErasedClient(client: pg.PoolClient, merchantId: string, customerId: string): Promise<boolean> {
    const result = await client.query(
      `SELECT 1 FROM customers.erasure_tombstones WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return Boolean(result.rowCount);
  }

  async loadCustomerPii(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
  ): Promise<{
    email: string | null;
    name: string | null;
    phone: string | null;
    external_reference: string | null;
    emails: string[];
    destinations: string[];
  }> {
    const customer = await client.query<{
      email: string; name: string; phone: string | null; external_reference: string; status: string;
    }>(
      `SELECT email,name,phone,external_reference,status FROM customers.customers
       WHERE merchant_id=$1 AND id=$2 FOR UPDATE`,
      [merchantId, customerId],
    );
    const contacts = await client.query<{ value: string }>(
      `SELECT value FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2 AND kind='email'`,
      [merchantId, customerId],
    );
    const prefs = await client.query<{ destination: string }>(
      `SELECT destination FROM operations.notification_preferences
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    const deliveries = await client.query<{ destination: string }>(
      `SELECT DISTINCT destination FROM operations.email_deliveries
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    const notifications = await client.query<{ destination: string }>(
      `SELECT DISTINCT destination FROM operations.notifications
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    const analytics = await client.query<{ email: string | null }>(
      `SELECT DISTINCT email FROM operations.analytics_events
       WHERE merchant_id=$1 AND customer_id=$2 AND email IS NOT NULL`,
      [merchantId, customerId],
    );
    const row = customer.rows[0];
    const emails = new Set<string>();
    const destinations = new Set<string>();
    if (row?.email) emails.add(row.email);
    for (const contact of contacts.rows) emails.add(contact.value);
    for (const pref of prefs.rows) destinations.add(pref.destination);
    for (const delivery of deliveries.rows) destinations.add(delivery.destination);
    for (const notification of notifications.rows) destinations.add(notification.destination);
    for (const event of analytics.rows) if (event.email) emails.add(event.email);
    for (const email of emails) destinations.add(email);
    return {
      email: row?.email ?? null,
      name: row?.name ?? null,
      phone: row?.phone ?? null,
      external_reference: row?.external_reference ?? null,
      emails: [...emails],
      destinations: [...destinations],
    };
  }
}
