{"path":"/workspace/source/apps/customer-service/src/erasure-service.ts","command":"create","file_text":"import { createHash } from 'node:crypto';
import { Redis } from 'ioredis';
import type pg from 'pg';
import { v4 as uuid } from 'uuid';
import { config } from '../../../packages/config/src/index.js';
import { transaction } from '../../../packages/database/src/pool.js';
import { deleteMailpitMessagesForRecipient } from '../../../packages/notifications/src/mailpit.js';
import { logger } from '../../../packages/observability/src/logger.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../../../packages/storage/src/minio.js';
import {
  completeIdempotency,
  requestHash,
  reserveIdempotency,
} from '../../payment-service/src/idempotency.js';
import {
  ErasureRepository,
  toErasurePublicView,
  type ErasurePublicView,
  type ErasureRequestRow,
} from './erasure-repository.js';

const ERASED_TOKEN = 'erased';
const ERASED_EMAIL = 'erased@deleted.invalid';
const ERASED_NAME = 'Erased Customer';
const ERASED_PHONE = null;
const ERASED_EXTERNAL = 'erased';

const STEP_COLLECT = 'collect_identifiers';
const STEP_TOMBSTONE = 'write_tombstone';
const STEP_PAYMENTS = 'redact_payments';
const STEP_CUSTOMER_GRAPH = 'erase_customer_graph';
const STEP_NOTIFICATIONS = 'erase_notifications';
const STEP_ANALYTICS = 'erase_analytics';
const STEP_AUDIT = 'redact_audit';
const STEP_DOCUMENTS = 'erase_documents';
const STEP_SEARCH = 'erase_search';
const STEP_CACHE = 'erase_cache';
const STEP_MAILPIT = 'erase_mailpit';
const STEP_PROVIDER = 'erase_provider';
const STEP_OUTBOX = 'redact_outbox';
const STEP_JOBS = 'redact_jobs';
const STEP_COMPLETE = 'mark_complete';

const ALL_STEPS = [
  STEP_COLLECT,
  STEP_TOMBSTONE,
  STEP_PAYMENTS,
  STEP_CUSTOMER_GRAPH,
  STEP_NOTIFICATIONS,
  STEP_ANALYTICS,
  STEP_AUDIT,
  STEP_DOCUMENTS,
  STEP_SEARCH,
  STEP_CACHE,
  STEP_MAILPIT,
  STEP_PROVIDER,
  STEP_OUTBOX,
  STEP_JOBS,
  STEP_COMPLETE,
] as const;

type CollectedIdentifiers = {
  emails: string[];
  destinations: string[];
  originalEmail: string | null;
};

function redactSnapshot(value: unknown): Record<string, unknown> {
  const source = value && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : {};
  return {
    ...source,
    id: typeof source.id === 'string' ? source.id : undefined,
    email: ERASED_EMAIL,
    name: ERASED_NAME,
    phone: ERASED_PHONE,
    external_reference: ERASED_EXTERNAL,
    externalReference: ERASED_EXTERNAL,
    status: typeof source.status === 'string' ? source.status : 'erased',
  };
}

function scrubObject(value: unknown): unknown {
  if (Array.isArray(value)) return value.map((item) => scrubObject(item));
  if (!value || typeof value !== 'object') return value;
  const result: Record<string, unknown> = {};
  for (const [key, nested] of Object.entries(value as Record<string, unknown>)) {
    const lower = key.toLowerCase();
    if (lower.includes('email')) result[key] = ERASED_EMAIL;
    else if (lower === 'name' || lower === 'displayname' || lower === 'billingname' || lower.endsWith('name')) {
      result[key] = ERASED_NAME;
    } else if (lower.includes('phone')) result[key] = ERASED_PHONE;
    else if (lower.includes('external_reference') || lower.includes('externalreference')) {
      result[key] = ERASED_EXTERNAL;
    } else if (lower === 'line1' || lower === 'line2' || lower === 'city' || lower === 'region'
      || lower === 'postal_code' || lower === 'postalcode' || lower === 'country'
      || lower === 'destination' || lower === 'to' || lower === 'address') {
      result[key] = ERASED_TOKEN;
    } else if (lower === 'body' || lower === 'subject' || lower === 'text_body' || lower === 'html_body'
      || lower === 'textbody' || lower === 'htmlbody') {
      result[key] = ERASED_TOKEN;
    } else if (nested && typeof nested === 'object') result[key] = scrubObject(nested);
    else result[key] = nested;
  }
  return result;
}

export class ErasureService {
  private redis: Redis | undefined;

  constructor(private readonly repository = new ErasureRepository()) {}

  private getRedis(): Redis {
    this.redis ??= new Redis(config().REDIS_URL);
    return this.redis;
  }

  async createRequest(
    merchantId: string,
    customerId: string,
    idempotencyKey: string,
  ): Promise<{ status: number; body: ErasurePublicView | { error: string } }> {
    if (!(await this.repository.customerExists(merchantId, customerId))) {
      return { status: 404, body: { error: 'customer_not_found' } };
    }

    const hash = requestHash({ customerId });
    try {
      return await transaction(async (client) => {
        const replay = await reserveIdempotency(
          client, merchantId, 'customer-erasure', idempotencyKey, hash,
        );
        if (replay) {
          return { status: replay.status, body: replay.body as ErasurePublicView };
        }

        const row = await this.repository.createOrGetExisting(client, merchantId, customerId);
        if (row.status === 'failed') {
          await client.query(
            `UPDATE customers.erasure_requests
             SET status='pending', updated_at=now(), last_error=NULL
             WHERE id=$1 AND status='failed'`,
            [row.id],
          );
          row.status = 'pending';
          row.last_error = null;
          row.updated_at = new Date();
        }

        const body = toErasurePublicView(row);
        await completeIdempotency(client, merchantId, 'customer-erasure', idempotencyKey, 202, body);
        await client.query(
          `INSERT INTO platform.audit_logs(merchant_id,actor_type,target_type,target_id,action,metadata,correlation_id)
           VALUES($1,'api_key','erasure_request',$2,'erasure.requested',$3,$4)`,
          [merchantId, row.id, { customerId }, uuid()],
        );
        return { status: 202, body };
      });
    } catch (error) {
      const status = typeof (error as { statusCode?: unknown }).statusCode === 'number'
        ? (error as { statusCode: number }).statusCode
        : undefined;
      if (status === 409) {
        return { status: 409, body: { error: 'idempotency_key_conflict' } };
      }
      throw error;
    }
  }

  async getRequest(merchantId: string, requestId: string): Promise<ErasurePublicView | undefined> {
    const row = await this.repository.findById(merchantId, requestId);
    return row ? toErasurePublicView(row) : undefined;
  }

  async processNext(workerId: string): Promise<boolean> {
    const request = await this.repository.claimNext(workerId);
    if (!request) return false;
    try {
      await this.processRequest(request);
    } catch (error) {
      const code = error instanceof Error && /^[a-z0-9_]+$/.test(error.message)
        ? error.message.slice(0, 80)
        : 'erasure_step_failed';
      logger.error({ error, requestId: request.id, code }, 'erasure request failed');
      await this.repository.markFailed(request.id, code);
    }
    return true;
  }

  private async processRequest(request: ErasureRequestRow): Promise<void> {
    let identifiers: CollectedIdentifiers = { emails: [], destinations: [], originalEmail: null };
    const completed = new Set(request.completed_steps);

    if (!completed.has(STEP_COLLECT)) {
      identifiers = await transaction(async (client) => {
        const pii = await this.repository.loadCustomerPii(client, request.merchant_id, request.customer_id);
        await client.query(
          `UPDATE customers.erasure_requests
           SET completed_steps = CASE WHEN $2 = ANY(completed_steps) THEN completed_steps
                                      ELSE array_append(completed_steps, $2) END,
               updated_at=now()
           WHERE id=$1`,
          [request.id, STEP_COLLECT],
        );
        // stash identifiers on the request via a side table in completed work is hard;
        // re-load from still-present sources below if needed.
        return {
          emails: pii.emails,
          destinations: pii.destinations,
          originalEmail: pii.email,
        };
      });
      completed.add(STEP_COLLECT);
    } else {
      identifiers = await transaction(async (client) => {
        const pii = await this.repository.loadCustomerPii(client, request.merchant_id, request.customer_id);
        const payments = await client.query<{ email: string | null }>(
          `SELECT DISTINCT customer_snapshot->>'email' AS email
           FROM payments.payment_intents
           WHERE merchant_id=$1 AND customer_id=$2 AND customer_snapshot->>'email' IS NOT NULL`,
          [request.merchant_id, request.customer_id],
        );
        const refunds = await client.query<{ customer_email: string | null }>(
          `SELECT DISTINCT customer_email FROM payments.refunds
           WHERE merchant_id=$1 AND payment_intent_id IN (
             SELECT id FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2
           )`,
          [request.merchant_id, request.customer_id],
        );
        const emails = new Set(pii.emails);
        for (const row of payments.rows) if (row.email && row.email !== ERASED_EMAIL) emails.add(row.email);
        for (const row of refunds.rows) if (row.customer_email && row.customer_email !== ERASED_EMAIL) emails.add(row.customer_email);
        const destinations = new Set(pii.destinations);
        for (const email of emails) destinations.add(email);
        return {
          emails: [...emails],
          destinations: [...destinations],
          originalEmail: pii.email && pii.email !== ERASED_EMAIL ? pii.email : null,
        };
      });
    }

    if (!completed.has(STEP_TOMBSTONE)) {
      await transaction(async (client) => {
        await this.repository.insertTombstone(client, request.merchant_id, request.customer_id, request.id);
        await this.repository.markStepComplete(client, request.id, STEP_TOMBSTONE);
      });
      completed.add(STEP_TOMBSTONE);
    }

    if (!completed.has(STEP_PAYMENTS)) {
      await transaction(async (client) => {
        await this.redactPayments(client, request.merchant_id, request.customer_id);
        await this.repository.markStepComplete(client, request.id, STEP_PAYMENTS);
      });
      completed.add(STEP_PAYMENTS);
    }

    if (!completed.has(STEP_CUSTOMER_GRAPH)) {
      await transaction(async (client) => {
        await this.eraseCustomerGraph(client, request.merchant_id, request.customer_id);
        await this.repository.markStepComplete(client, request.id, STEP_CUSTOMER_GRAPH);
      });
      completed.add(STEP_CUSTOMER_GRAPH);
    }

    if (!completed.has(STEP_NOTIFICATIONS)) {
      await transaction(async (client) => {
        await this.eraseNotifications(client, request.merchant_id, request.customer_id);
        await this.repository.markStepComplete(client, request.id, STEP_NOTIFICATIONS);
      });
      completed.add(STEP_NOTIFICATIONS);
    }

    if (!completed.has(STEP_ANALYTICS)) {
      await transaction(async (client) => {
        await this.eraseAnalytics(client, request.merchant_id, request.customer_id);
        await this.repository.markStepComplete(client, request.id, STEP_ANALYTICS);
      });
      completed.add(STEP_ANALYTICS);
    }

    if (!completed.has(STEP_AUDIT)) {
      await transaction(async (client) => {
        await this.redactAuditLogs(client, request.merchant_id, request.customer_id);
        await this.repository.markStepComplete(client, request.id, STEP_AUDIT);
      });
      completed.add(STEP_AUDIT);
    }

    if (!completed.has(STEP_DOCUMENTS)) {
      await this.eraseDocuments(request.merchant_id, request.customer_id);
      await transaction(async (client) => {
        await this.repository.markStepComplete(client, request.id, STEP_DOCUMENTS);
      });
      completed.add(STEP_DOCUMENTS);
    }

    if (!completed.has(STEP_SEARCH)) {
      await this.eraseSearch(request.merchant_id, request.customer_id);
      await transaction(async (client) => {
        await this.repository.markStepComplete(client, request.id, STEP_SEARCH);
      });
      completed.add(STEP_SEARCH);
    }

    if (!completed.has(STEP_CACHE)) {
      await this.eraseCache(request.merchant_id, request.customer_id);
      await transaction(async (client) => {
        await this.repository.markStepComplete(client, request.id, STEP_CACHE);
      });
      completed.add(STEP_CACHE);
    }

    if (!completed.has(STEP_MAILPIT)) {
      await this.eraseMailpit(identifiers.destinations);
      await transaction(async (client) => {
        await this.repository.markStepComplete(client, request.id, STEP_MAILPIT);
      });
      completed.add(STEP_MAILPIT);
    }

    if (!completed.has(STEP_PROVIDER)) {
      await transaction(async (client) => {
        await this.eraseProvider(client, request.merchant_id, request.customer_id);
        await this.repository.markStepComplete(client, request.id, STEP_PROVIDER);
      });
      completed.add(STEP_PROVIDER);
    }

    if (!completed.has(STEP_OUTBOX)) {
      await transaction(async (client) => {
        await this.redactOutbox(client, request.merchant_id, request.customer_id);
        await this.repository.markStepComplete(client, request.id, STEP_OUTBOX);
      });
      completed.add(STEP_OUTBOX);
    }

    if (!completed.has(STEP_JOBS)) {
      await transaction(async (client) => {
        await this.redactJobs(client, request.merchant_id, request.customer_id);
        await this.repository.markStepComplete(client, request.id, STEP_JOBS);
      });
      completed.add(STEP_JOBS);
    }

    if (!completed.has(STEP_COMPLETE)) {
      await transaction(async (client) => {
        await this.repository.markStepComplete(client, request.id, STEP_COMPLETE);
        await this.repository.markCompleted(client, request.id);
        await client.query(
          `INSERT INTO platform.audit_logs(merchant_id,actor_type,target_type,target_id,action,metadata,correlation_id)
           VALUES($1,'system','erasure_request',$2,'erasure.completed',$3,$4)`,
          [request.merchant_id, request.id, { customerId: request.customer_id, steps: ALL_STEPS }, uuid()],
        );
      });
    }
  }

  private async redactPayments(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    const intents = await client.query<{ id: string; customer_snapshot: Record<string, unknown> }>(
      `SELECT id, customer_snapshot FROM payments.payment_intents
       WHERE merchant_id=$1 AND customer_id=$2 FOR UPDATE`,
      [merchantId, customerId],
    );
    for (const intent of intents.rows) {
      await client.query(
        `UPDATE payments.payment_intents
         SET customer_snapshot=$2, description=CASE
           WHEN description IS NULL THEN NULL ELSE $3 END, updated_at=now()
         WHERE id=$1`,
        [intent.id, redactSnapshot(intent.customer_snapshot), ERASED_TOKEN],
      );
      await client.query(
        `UPDATE payments.payment_attempts
         SET request_payload = COALESCE(request_payload, '{}'::jsonb) - 'customerEmail' - 'email' - 'name' - 'phone',
             response_payload = CASE
               WHEN response_payload IS NULL THEN NULL
               ELSE COALESCE(response_payload, '{}'::jsonb) - 'customerEmail' - 'email' - 'name' - 'phone'
             END,
             failure_message = CASE WHEN failure_message IS NULL THEN NULL ELSE left(failure_message, 80) END
         WHERE payment_intent_id=$1`,
        [intent.id],
      );
      await client.query(
        `UPDATE payments.refunds SET customer_email=$2 WHERE payment_intent_id=$1`,
        [intent.id, ERASED_EMAIL],
      );
      await client.query(
        `UPDATE payments.disputes
         SET evidence = CASE
           WHEN evidence IS NULL THEN '{}'::jsonb
           ELSE jsonb_build_object('redacted', true)
         END
         WHERE payment_intent_id=$1`,
        [intent.id],
      );
    }

    const invoices = await client.query<{ id: string; billing_snapshot: Record<string, unknown>; object_key: string | null }>(
      `SELECT id, billing_snapshot, object_key FROM payments.invoices
       WHERE merchant_id=$1 AND customer_id=$2 FOR UPDATE`,
      [merchantId, customerId],
    );
    for (const invoice of invoices.rows) {
      await client.query(
        `UPDATE payments.invoices SET billing_snapshot=$2 WHERE id=$1`,
        [invoice.id, redactSnapshot(invoice.billing_snapshot)],
      );
    }
  }

  private async eraseCustomerGraph(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `DELETE FROM customers.addresses WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `DELETE FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `DELETE FROM customers.payment_method_refs WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `DELETE FROM customers.provider_customer_mappings WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );

    const tickets = await client.query<{ ticket_id: string }>(
      `SELECT ticket_id FROM customers.support_participants WHERE customer_id=$1`,
      [customerId],
    );
    for (const ticket of tickets.rows) {
      const others = await client.query(
        `SELECT 1 FROM customers.support_participants
         WHERE ticket_id=$1 AND customer_id<>$2 LIMIT 1`,
        [ticket.ticket_id, customerId],
      );
      await client.query(
        `DELETE FROM customers.support_participants WHERE ticket_id=$1 AND customer_id=$2`,
        [ticket.ticket_id, customerId],
      );
      if (!others.rowCount) {
        await client.query(
          `UPDATE customers.support_messages
           SET body=$3, attachments='[]'::jsonb, author_id=NULL
           WHERE merchant_id=$1 AND ticket_id=$2`,
          [merchantId, ticket.ticket_id, ERASED_TOKEN],
        );
        await client.query(
          `UPDATE customers.support_tickets SET subject=$3 WHERE merchant_id=$1 AND id=$2`,
          [merchantId, ticket.ticket_id, ERASED_TOKEN],
        );
      } else {
        await client.query(
          `UPDATE customers.support_messages
           SET body=$3, attachments='[]'::jsonb
           WHERE merchant_id=$1 AND ticket_id=$2 AND author_id=$4`,
          [merchantId, ticket.ticket_id, ERASED_TOKEN, customerId],
        );
      }
    }

    // Keep the customer row as a non-identifying tombstone so FK-bearing financial
    // records remain valid, while ordinary reads no longer surface personal data.
    const erasedRef = `erased:${customerId}`;
    const erasedEmail = `erased+${customerId.replaceAll('-', '')}@deleted.invalid`;
    await client.query(
      `UPDATE customers.customers
       SET email=$3, name=$4, phone=NULL, external_reference=$5, metadata='{}'::jsonb,
           status='erased', version=version+1, updated_at=now()
       WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId, erasedEmail, ERASED_NAME, erasedRef],
    );

    await client.query(
      `UPDATE customers.customer_imports SET status='erased'
       WHERE merchant_id=$1 AND object_key LIKE $2`,
      [merchantId, `${merchantId}/imports/%`],
    );
  }

