    );
  }

  private async eraseDocuments(merchantId: string, customerId: string): Promise<void> {
    await transaction(async (client) => {
      const manifests = await client.query<{ object_key: string; document_type: string; metadata: Record<string, unknown> }>(
        `SELECT object_key, document_type, metadata FROM operations.document_manifests
         WHERE merchant_id=$1 AND customer_id=$2`,
        [merchantId, customerId],
      );
      for (const manifest of manifests.rows) {
        if (manifest.document_type === 'customer_import') {
          try {
            await objectStore.removeObject(DOCUMENT_BUCKET, manifest.object_key);
          } catch {
            // Object may already be gone; continue converging.
          }
          await client.query(
            `DELETE FROM operations.document_manifests WHERE object_key=$1`,
            [manifest.object_key],
          );
          continue;
        }

        const redactedBody = JSON.stringify({
          redacted: true,
          documentType: manifest.document_type,
          issuedAt: new Date().toISOString(),
          customer: { id: customerId, email: ERASED_EMAIL, name: ERASED_NAME },
          metadata: scrubObject(manifest.metadata),
        });
        await objectStore.putObject(
          DOCUMENT_BUCKET,
          manifest.object_key,
          redactedBody,
          Buffer.byteLength(redactedBody),
          { 'Content-Type': 'application/json' },
        );
        await client.query(
          `UPDATE operations.document_manifests
           SET checksum=$2, metadata=$3::jsonb, customer_id=$4
           WHERE object_key=$1`,
          [
            manifest.object_key,
            createHash('sha256').update(redactedBody).digest('hex'),
            JSON.stringify({ ...scrubObject(manifest.metadata) as object, redacted: true }),
            customerId,
          ],
        );
      }

      // Also scrub invoice object keys referenced without manifests if needed.
      const invoices = await client.query<{ object_key: string | null }>(
        `SELECT object_key FROM payments.invoices WHERE merchant_id=$1 AND customer_id=$2 AND object_key IS NOT NULL`,
        [merchantId, customerId],
      );
      for (const invoice of invoices.rows) {
        if (!invoice.object_key) continue;
        const exists = manifests.rows.some((row) => row.object_key === invoice.object_key);
        if (exists) continue;
        const redactedBody = JSON.stringify({
          redacted: true,
          documentType: 'invoice',
          customer: { id: customerId, email: ERASED_EMAIL, name: ERASED_NAME },
        });
        try {
          await objectStore.putObject(
            DOCUMENT_BUCKET,
            invoice.object_key,
            redactedBody,
            Buffer.byteLength(redactedBody),
            { 'Content-Type': 'application/json' },
          );
        } catch {
          // ignore missing bucket/object races
        }
      }
    });
  }

  private async eraseSearch(merchantId: string, customerId: string): Promise<void> {
    try {
      await searchClient.delete({
