        refresh: true,
      });
    } catch (error) {
      const status = (error as { meta?: { statusCode?: number } }).meta?.statusCode;
      if (status !== 404) throw error;
    }
  }

  private async eraseCache(merchantId: string, customerId: string): Promise<void> {
    const redis = this.getRedis();
    const cacheKey = `merchant:${merchantId}:customer:${customerId}`;
    await redis.del(cacheKey, `${cacheKey}:activity`);
  }

  private async eraseMailpit(destinations: string[]): Promise<void> {
    for (const destination of destinations) {
      if (!destination || destination === ERASED_EMAIL || destination === ERASED_TOKEN) continue;
      await deleteMailpitMessagesForRecipient(destination);
    }
  }

  private async eraseProvider(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE provider_sandbox.customers
       SET email=$3, name=$4, external_reference=$5, updated_at=now()
       WHERE merchant_id=$1 AND payflow_customer_id=$2`,
      [merchantId, customerId, ERASED_EMAIL, ERASED_NAME, ERASED_EXTERNAL],
    );
  }

  private async redactOutbox(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE operations.outbox_events
       SET payload = jsonb_set(
         jsonb_set(
           jsonb_set(payload, '{email}', to_jsonb($3::text), true),
           '{customerEmail}', to_jsonb($3::text), true
         ),
         '{name}', to_jsonb($4::text), true
       )
       WHERE merchant_id=$1
         AND (
           aggregate_id=$2
           OR payload->>'customerId'=$2
         )`,
      [merchantId, customerId, ERASED_EMAIL, ERASED_NAME],
    );
  }

  private async redactJobs(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE operations.jobs
       SET payload = jsonb_set(
         COALESCE(payload, '{}'::jsonb),
         '{customerSnapshot}',
         $3::jsonb,
         true
       )
       WHERE merchant_id=$1
         AND payload->>'customerId'=$2`,
